begin;
create extension if not exists pgtap with schema extensions;
set local search_path=public,extensions;
select no_plan();
create temp table inv_case(name text primary key,id uuid,key uuid default gen_random_uuid(),result jsonb,snapshot jsonb);
grant all on inv_case to authenticated;
create function pg_temp.customer() returns uuid language sql as $$select '31000000-0000-4000-8000-000000000001'::uuid$$;
create function pg_temp.product() returns uuid language sql security definer set search_path='' as $$select id from public.products where sku='TEST-A'$$;
create function pg_temp.unit() returns uuid language sql security definer set search_path='' as $$select id from public.product_units where product_id=pg_temp.product() and unit_name='adet'$$;
create function pg_temp.cart() returns jsonb language sql as $$select jsonb_build_array(jsonb_build_object('unit_id',pg_temp.unit(),'quantity',4))$$;
select set_config('request.jwt.claim.sub','30000000-0000-4000-8000-000000000001',true);
set local role authenticated;
insert into inv_case(name,id) values('order',(checkout_cart(pg_temp.customer(),pg_temp.cart(),quote_cart(pg_temp.customer(),pg_temp.cart()),gen_random_uuid())->>'order_id')::uuid);
reset role;
insert into inv_case(name,id,snapshot) select 'item',i.id,to_jsonb(i) from order_items i join inv_case s on s.id=i.order_id where s.name='order';
insert into inv_case(name,snapshot) select 'stock',to_jsonb(i) from inventory i where product_id=pg_temp.product();
set local role anon;
select throws_ok($$select warehouse_workspace('stock')$$,'42501',null::text,'Anon cannot read workspace');
select throws_ok($$select receive_inventory(pg_temp.unit(),1,'',gen_random_uuid())$$,'42501',null::text,'Anon cannot receive');
reset role;
set local role authenticated;
select throws_ok($$select warehouse_workspace('stock')$$,'42501',null::text,'Customer cannot read warehouse');
select throws_ok($$select warehouse_order_action(id,'start',null,null,key) from inv_case where name='order'$$,'42501',null::text,'Customer cannot start picking');
select set_config('request.jwt.claim.sub','30000000-0000-4000-8000-000000000002',true);
select throws_ok($$select warehouse_workspace('stock')$$,'42501',null::text,'Sales cannot read warehouse');
select throws_ok($$select receive_inventory(pg_temp.unit(),1,'',gen_random_uuid())$$,'42501',null::text,'Sales cannot receive');
select set_config('request.jwt.claim.sub','30000000-0000-4000-8000-000000000004',true);
select throws_ok($$select receive_inventory(pg_temp.unit(),1,'',gen_random_uuid())$$,'42501',null::text,'Accounting cannot receive');
select throws_ok($$select warehouse_workspace('counts')$$,'42501',null::text,'Accounting cannot read counts');
select set_config('request.jwt.claim.sub','30000000-0000-4000-8000-000000000005',true);
select throws_ok($$select warehouse_order_action(id,'start',null,null,key) from inv_case where name='order'$$,'42501',null::text,'Driver cannot start picking');
select set_config('request.jwt.claim.sub','30000000-0000-4000-8000-000000000003',true);
select results_eq($$select jsonb_object_keys(warehouse_workspace('stock')->0) order by 1$$,
 $$values ('available'),('id'),('name'),('physical'),('reserved'),('unit'),('units')$$,'Stock exact field allowlist excludes price');
select results_eq($$select jsonb_object_keys(warehouse_workspace('preparation')->0) order by 1$$,
 $$values ('items'),('order_id'),('status')$$,'Queue excludes customer identity and money');
select results_eq($$select jsonb_object_keys(warehouse_workspace('preparation')->0->'items'->0) order by 1$$,
 $$values ('conversion'),('id'),('name'),('picked'),('quantity'),('unit')$$,'Preparation item exact safe fields');
select throws_ok($$select warehouse_workspace('prices')$$,'22023',null::text,'Unknown section denied');
select throws_ok($$update inventory set physical_qty=1000$$,'42501',null::text,'Raw stock writes closed');
select throws_ok($$select * from private.warehouse_receipts$$,'42501',null::text,'Receipts private');
select throws_ok($$select warehouse_order_action((select id from inv_case where name='order'),'pick',(select id from inv_case where name='item'),1,gen_random_uuid())$$,'23514',null::text,'Pick before start denied');
update inv_case set result=warehouse_order_action(id,'start',null,null,key) where name='order';
select is((select result->>'status' from inv_case where name='order'),'picking','Submitted starts picking');
select is(warehouse_order_action(id,'start',null,null,key),result,'Start replay returns original response') from inv_case where name='order';
select throws_ok($$select warehouse_order_action(id,'load',null,null,key) from inv_case where name='order'$$,'22023',null::text,'Key cannot change action');
select throws_ok($$select warehouse_order_action(id,'load',null,null,gen_random_uuid()) from inv_case where name='order'$$,'23514',null::text,'Partial picking cannot load');
select throws_ok($$select warehouse_order_action((select id from inv_case where name='order'),'pick',gen_random_uuid(),1,gen_random_uuid())$$,'23514',null::text,'Foreign item rejected');
select throws_ok($$select warehouse_order_action((select id from inv_case where name='order'),'pick',(select id from inv_case where name='item'),0,gen_random_uuid())$$,'22023',null::text,'Zero pick rejected');
select throws_ok($$select warehouse_order_action((select id from inv_case where name='order'),'pick',(select id from inv_case where name='item'),5,gen_random_uuid())$$,'23514',null::text,'Overpick rejected');
-- Change current conversion; historical order still consumes original 1.
reset role;
update product_units set conversion_to_base=2 where id=pg_temp.unit();
set local role authenticated;
update inv_case set result=warehouse_order_action((select id from inv_case where name='order'),'pick',id,1,key) where name='item';
select is((select result->>'status' from inv_case where name='item'),'picking','Partial pick stays picking');
select is(warehouse_order_action((select id from inv_case where name='order'),'pick',id,1,key),result,'Partial pick replay') from inv_case where name='item';
reset role;
select is((select picked_qty from order_items where id=(select id from inv_case where name='item')),1,'Replay picks once');
select is((select physical_qty::numeric from inventory where product_id=pg_temp.product()),(select (snapshot->>'physical_qty')::numeric-1 from inv_case where name='stock'),'Historical conversion used');
select is((select reserved_qty::numeric from inventory where product_id=pg_temp.product()),(select (snapshot->>'reserved_qty')::numeric-1 from inv_case where name='stock'),'Reservation consumed equally');
select is((select to_jsonb(i)-'picked_qty' from order_items i where id=(select id from inv_case where name='item')),
 (select snapshot-'picked_qty' from inv_case where name='item'),'Price/quantity/exact snapshots unchanged');
set local role authenticated;
select is(warehouse_order_action((select id from inv_case where name='order'),'pick',(select id from inv_case where name='item'),3,gen_random_uuid())->>'status','picked','Final pick advances once');
select throws_ok($$select warehouse_order_action((select id from inv_case where name='order'),'load',null,null,gen_random_uuid())$$,'23514',null::text,'Load without active assignment rejected');
reset role;
insert into inv_case(name,id) values('run',gen_random_uuid());
insert into delivery_runs(id,vehicle_id,primary_driver_id,status)
 select s.id,v.id,'30000000-0000-4000-8000-000000000005','fixture' from inv_case s cross join vehicles v where s.name='run';
insert into delivery_stops(run_id,order_id,sequence,status,assigned_by)
 values((select id from inv_case where name='run'),(select id from inv_case where name='order'),1,'fixture','30000000-0000-4000-8000-000000000006');
update inv_case set snapshot=(select to_jsonb(i) from inventory i where product_id=pg_temp.product()) where name='stock';
set local role authenticated;
select is(warehouse_order_action((select id from inv_case where name='order'),'load',null,null,gen_random_uuid())->>'status','loaded','Active assigned fully picked order loads');
reset role;
select is((select to_jsonb(i) from inventory i where product_id=pg_temp.product()),(select snapshot from inv_case where name='stock'),'Load has zero stock effect');
select is((select count(*) from order_status_history where order_id=(select id from inv_case where name='order') and to_status in ('picking','picked','loaded')),3::bigint,'Three transitions each recorded once');
select is((select sum(reserved_delta) from inventory_movements where order_item_id=(select id from inv_case where name='item')),0::numeric,'Reservation fully consumed');
select is((select count(*) from inventory_movements where order_item_id=(select id from inv_case where name='item') and type='picked'),2::bigint,'Two partial pick facts only');
set local role authenticated;
select throws_ok($$select receive_inventory(pg_temp.unit(),0,'',gen_random_uuid())$$,'22023',null::text,'Zero receiving rejected');
select throws_ok($$select receive_inventory(pg_temp.unit(),'NaN','',gen_random_uuid())$$,'22023',null::text,'Nonfinite receiving rejected');
insert into inv_case(name) values('receive');
update inv_case set result=receive_inventory(pg_temp.unit(),0.125,'Synthetic receipt',key) where name='receive';
select is((select result->>'base_quantity' from inv_case where name='receive'),'0.250','Receiving exact decimal, no rounding');
select is(receive_inventory(pg_temp.unit(),0.125,'Synthetic receipt',key),result,'Receiving retry is idempotent') from inv_case where name='receive';
select throws_ok($$select receive_inventory(pg_temp.unit(),0.5,'Synthetic receipt',key) from inv_case where name='receive'$$,'22023',null::text,'Receiving different payload denied');
reset role;
select is((select count(*) from inventory_movements where operation_key=(select key from inv_case where name='receive')),1::bigint,'Receiving movement once');
select is((select reserved_qty::numeric from inventory where product_id=pg_temp.product()),(select (snapshot->>'reserved_qty')::numeric from inv_case where name='stock'),'Receiving does not change reserved');
update profiles set active=false where id='30000000-0000-4000-8000-000000000003';
set local role authenticated;
select throws_ok($$select receive_inventory(pg_temp.unit(),0.125,'Synthetic receipt',key) from inv_case where name='receive'$$,'42501',null::text,'Inactive actor cannot replay');
select throws_ok($$select warehouse_workspace('stock')$$,'42501',null::text,'Inactive actor cannot read');
reset role;
update profiles set active=true where id='30000000-0000-4000-8000-000000000003';
set local role authenticated;
select throws_ok($$select submit_stock_count('[]','',gen_random_uuid())$$,'22023',null::text,'Empty count denied');
insert into inv_case(name,id) values('count',(submit_stock_count(jsonb_build_array(jsonb_build_object('product_id',pg_temp.product(),'counted_qty','95')),'Synthetic count',gen_random_uuid())->>'count_id')::uuid);
select throws_ok($$select approve_stock_count(id,key) from inv_case where name='count'$$,'42501',null::text,'Warehouse cannot approve own count');
reset role;
select is((select status from stock_counts where id=(select id from inv_case where name='count')),'pending','Count is pending');
select is((select physical_qty::numeric from inventory where product_id=pg_temp.product()),(select (snapshot->>'physical_qty')::numeric+0.25 from inv_case where name='stock'),'Submission does not change stock');
select set_config('request.jwt.claim.sub','30000000-0000-4000-8000-000000000006',true);
set local role authenticated;
select throws_ok($$select submit_stock_count(jsonb_build_array(jsonb_build_object('product_id',pg_temp.product(),'counted_qty','95')),'',gen_random_uuid())$$,'42501',null::text,'Manager does not get Warehouse count entry permission');
update inv_case set result=approve_stock_count(id,key) where name='count';
select is((select result->>'status' from inv_case where name='count'),'approved','Manager approves');
select is(approve_stock_count(id,key),result,'Approval replay is idempotent') from inv_case where name='count';
select throws_ok($$select approve_stock_count(id,gen_random_uuid()) from inv_case where name='count'$$,'23514',null::text,'New key cannot reapprove');
reset role;
select is((select physical_qty::numeric from inventory where product_id=pg_temp.product()),95::numeric,'Approved physical stock equals count');
select is((select count(*) from inventory_movements where stock_count_id=(select id from inv_case where name='count')),1::bigint,'Single count adjustment');
select throws_ok($$update stock_count_items set counted_qty=99 where stock_count_id=(select id from inv_case where name='count')$$,'23514',null::text,'Approved count frozen');
select set_config('request.jwt.claim.sub','30000000-0000-4000-8000-000000000003',true);
set local role authenticated;
insert into inv_case(name,id) values('stale',(submit_stock_count(jsonb_build_array(jsonb_build_object('product_id',pg_temp.product(),'counted_qty','95')),'Stale',gen_random_uuid())->>'count_id')::uuid);
select receive_inventory(pg_temp.unit(),1,'Change after count',gen_random_uuid());
select set_config('request.jwt.claim.sub','30000000-0000-4000-8000-000000000007',true);
select throws_ok($$select approve_stock_count(id,key) from inv_case where name='stale'$$,'40001',null::text,'Changed stock requires recount');
reset role;
-- Restore the physical value: revision still detects an intervening movement.
update inventory set physical_qty=95 where product_id=pg_temp.product();
set local role authenticated;
select throws_ok($$select approve_stock_count(id,key) from inv_case where name='stale'$$,'40001',null::text,'ABA change detected even at same physical value');
select set_config('request.jwt.claim.sub','30000000-0000-4000-8000-000000000003',true);
insert into inv_case(name,id) values('below',(submit_stock_count(jsonb_build_array(jsonb_build_object('product_id',pg_temp.product(),'counted_qty','0')),'Below reservation',gen_random_uuid())->>'count_id')::uuid),
 ('rollback',(submit_stock_count(jsonb_build_array(jsonb_build_object('product_id',pg_temp.product(),'counted_qty','96')),'Rollback',gen_random_uuid())->>'count_id')::uuid);
select set_config('request.jwt.claim.sub','30000000-0000-4000-8000-000000000007',true);
select throws_ok($$select approve_stock_count(id,key) from inv_case where name='below'$$,'23514',null::text,'Cannot count below other reservations');
reset role;
create function pg_temp.reject_audit() returns trigger language plpgsql as $$begin raise exception using errcode='P0001',message='Injected audit failure'; end;$$;
insert into inv_case(name,id) select 'seed_item',id from order_items where order_id='35000000-0000-4000-8000-000000000001';
create trigger test_audit_failure before insert on audit_logs for each row execute function pg_temp.reject_audit();
set local role authenticated;
select throws_ok($$select warehouse_order_action('35000000-0000-4000-8000-000000000001','pick',id,1,gen_random_uuid()) from inv_case where name='seed_item'$$,
 'P0001',null::text,'Audit failure rejects picking transaction');
select throws_ok($$select approve_stock_count(id,key) from inv_case where name='rollback'$$,'P0001',null::text,'Audit failure rejects count transaction');
select throws_ok($$select receive_inventory(pg_temp.unit(),1,'Rollback',gen_random_uuid())$$,'P0001',null::text,'Audit failure rejects receiving transaction');
reset role;
select is((select picked_qty from order_items where id=(select id from inv_case where name='seed_item')),1,'Picked quantity rolls back with audit');
select is((select count(*) from inventory_movements where order_item_id=(select id from inv_case where name='seed_item') and type='picked'),1::bigint,'No failed pick movement survives');
select is((select physical_qty::numeric from inventory where product_id=pg_temp.product()),95::numeric,'Stock rolled back');
select is((select status from stock_counts where id=(select id from inv_case where name='rollback')),'pending','Count status rolled back');
select is((select count(*) from inventory_movements where stock_count_id=(select id from inv_case where name='rollback')),0::bigint,'Adjustment rolled back');
select is((select count(*) from private.warehouse_receipts where operation_key=(select key from inv_case where name='rollback')),0::bigint,'Receipt rolled back');
drop trigger test_audit_failure on audit_logs;
set local role authenticated;
select is(approve_stock_count(id,key)->>'status','approved','Owner can retry after rollback') from inv_case where name='rollback';
select is(jsonb_typeof(warehouse_workspace('movements')),'array','Owner reads movements');
select * from finish();
rollback;
